# Bitmap font renderer for 4-bit grayscale frame buffers
#
# Draws fonts generated by tools/fonts/make_fonts.py (modules in
# display/fonts/). Glyphs hold 4-bit coverage, which a 16-entry palette
# maps onto the requested gray level, so the antialiasing scales with the
# text colour. Each glyph is drawn with one FrameBuffer.blit() call.
#
#   from display.bitmapfont import BitmapFont
#   from display.fonts import b612_bold_30
#   big = BitmapFont(b612_bold_30)
#   big.text(display, "-12.34", x, y, 15)          # y is the top of the line
#   big.text(display, "433", x, y, 0, bg=15)       # inverted, filled box

import framebuf

_REC = 8   # Bytes per glyph record in the font's INDEX


class BitmapFont:
    def __init__(self, module):
        self.height = module.HEIGHT       # Line height in pixels
        self.baseline = module.BASELINE   # Baseline, from the top of the line
        self._chars = module.CHARS
        self._index = module.INDEX
        self._data = memoryview(module.DATA)
        self._glyphs = {}                 # char -> (advance, xoff, yoff, FrameBuffer)
        self._palettes = {}               # (col, bg) -> FrameBuffer

    def _glyph(self, ch):
        g = self._glyphs.get(ch)
        if g is not None:
            return g
        i = self._chars.find(ch)
        if i < 0:
            i = self._chars.find("?")
            if i < 0:
                return None
        r = self._index
        p = i * _REC
        adv = r[p]
        xoff = r[p + 1] - 256 if r[p + 1] > 127 else r[p + 1]
        yoff = r[p + 2] - 256 if r[p + 2] > 127 else r[p + 2]
        w = r[p + 3]
        h = r[p + 4]
        off = r[p + 6] | (r[p + 7] << 8)
        fb = None
        if w and h:
            fb = framebuf.FrameBuffer(self._data[off:off + w * h // 2],
                                      w, h, framebuf.GS4_HMSB)
        g = (adv, xoff, yoff, fb)
        self._glyphs[ch] = g
        return g

    def _palette(self, col, bg):
        key = (col, bg)
        pal = self._palettes.get(key)
        if pal is None:
            base = 0 if bg is None else bg
            pal = framebuf.FrameBuffer(bytearray(8), 16, 1, framebuf.GS4_HMSB)
            for a in range(16):
                pal.pixel(a, 0, base + ((col - base) * a + 7) // 15)
            self._palettes[key] = pal
        return pal

    def width(self, s):
        """Width of s in pixels (sum of advances)."""
        w = 0
        for ch in s:
            g = self._glyph(ch)
            if g:
                w += g[0]
        return w

    def text(self, target, s, x, y, col=15, bg=None):
        """
        Draw s with the top of the line at y.

        target: a FrameBuffer, or anything with a framebuf-style
                blit(fbuf, x, y, key, palette) and fill_rect (e.g. SSD1322).
        col:    gray level 0-15 of the text
        bg:     None to draw over what is there; a gray level to fill the
                text box (width(s) x height) with first.

        Returns the x position after the last character.
        """
        if bg is not None:
            target.fill_rect(x, y, self.width(s), self.height, bg)
        pal = self._palette(col, bg)
        # Transparent: skip pixels that map to 0. Opaque: draw every pixel.
        key = -1 if bg is not None else 0
        for ch in s:
            g = self._glyph(ch)
            if g is None:
                continue
            if g[3] is not None:
                target.blit(g[3], x + g[1], y + g[2], key, pal)
            x += g[0]
        return x

    def text_right(self, target, s, x_right, y, col=15, bg=None):
        """Draw s right-aligned so it ends at x_right (exclusive)."""
        return self.text(target, s, x_right - self.width(s), y, col, bg)
